//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS25100.xml";
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "2";
scwin.vRowCount = 0;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vProcsStatCd;
scwin.vgRowIdx = 1;
scwin.vsCoPopGb = "SCH";
scwin.vSelObj;
scwin.v_G_STD_CD = "";
scwin.v_G_BND_LIST_PROCS_TP_CD = "1";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: scwin.v_G_STD_CD,
        BND_LIST_PROCS_TP_CD: scwin.v_G_BND_LIST_PROCS_TP_CD,
        TAB_IDX: 2
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_list_sync
 * 설명       : 조회버튼을 클릭하면 목록을 조회한다.
 ***********************************************/
scwin.fn_list_sync = function() {
    var param = '';
    param += "&{P}V_LIST_STAT_CD=" + $c.stf.getObjectValue(cmb_BndStsGb);
    param += "&{P}V_STD_NM=" + txb_ISU_CD.getValue();
    param += "&{P}V_ISUR_NM=" + txb_ISUR_CD.getValue();
    var dsNm = 'BNS_LIST_BND_SRCH_LIST';
    var qryId = 'lds.stf.bnslist_bnd_srch.select.list';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명       : 그리드 선택 시 상세내역을 조회한다.
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)
    param += "&{P}V_STD_CD=" + scwin.v_G_STD_CD; //

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readBndIsuInfo';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);

    //기준금리상세(표면이자율,발행가액) --
    dsNm = 'BNS_COUPNRT_ISURPRC';
    qryId = 'lds.stf.bnscommon.select.readCoupnRtAndIsurPrc';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_CoupnRtAndIsurPrc, dsNm, qryId, param);

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listBndCredit';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);

    //인수기관정보
    dsNm = 'BNS_UDWRT_INST';
    qryId = 'lds.stf.bnscommon.select.listBndUdwrtInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);

    //원리금정보
    dsNm = 'BNS_PRINCINT_INFO';
    qryId = 'lds.stf.bnscommon.select.listBndPrincint';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Princint, dsNm, qryId, param);

    //CALL
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listBndOptionCall';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);

    //PUT
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listBndOptionPut';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);

    //변동금리
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listBndChgInt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listBndSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);

    //유동화자산
    dsNm = 'BNS_SECUTIZ_ASST';
    qryId = 'lds.stf.bnscommon.select.listBndSecutizAsst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SecutizAsst, dsNm, qryId, param);

    //주식관련 행사가격 조정 JACKAL_190220
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listBndStockRelExerPrcAdj';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};


/********************************************** 
