/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_IsuInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_IsuInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 반송 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetBndClss
 * 설명       : 채권분류 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetBndClss = function(arrPar) {
    arrPar[0] = {
        BND_CLSS_CD: "",
        BND_TP_NM: ""
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetBndClss
 * 설명       : 채권분류 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetBndClss = function(arrPar) {
    $c.stf.setObjectValue(txb_BndTpNm, arrPar[0].BND_TP_NM1);
    dts_IsuInfo.setCellData(1, "BND_CLSS_CD", arrPar[0].BND_CLSS_CD);
};


/********************************************** 
 * 함수명   : fn_GetStkcertIsu
 * 설명       : 주권종목 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetStkcertIsu = function(arrPar) {
    arrPar[0] = {
        STD_CD: '',
        ISU_NM: '',
        ISUR_CD: dts_IsuInfo.getCellData(1, "ISUR_CD"),
        POP_CALL_YN: 'Y'
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetStkcertIsu
 * 설명       : 주권종목 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetStkcertIsu = function(arrPar) {
    $c.stf.setObjectValue(txb_ObjIsuNm, arrPar[0].ISU_NM);
    $c.stf.setObjectValue(txb_ObjIsuCd, arrPar[0].STD_CD);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(scwin.vSelObj),
        ISUR_NM: $c.stf.getObjectValue(scwin.vSelObj)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    if (scwin.vsCoPopGb == "SCH") {
        $c.stf.setObjectValue(txb_COM_NM, arrPar[0].ISUR_NM);
        $c.stf.setObjectValue(txb_ISUR_CD, arrPar[0].ISUR_CD);
    } else {
        var cbdata = "^ ," + arrPar[0].ISUR_CD + "^" + arrPar[0].ISUR_NM;
        scwin.vSelObj.CBData = cbdata;
        $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].ISUR_CD);
    }
};



/********************************************** 
 * 함수명   : fn_GetParBndBasNm
 * 설명       : 종목기준명 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParBndBasNm = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: dts_IsuInfo.getCellData(1, "ISUR_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParBndBasNm
 * 설명       : 종목기준명 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParBndBasNm = function(arrPar) {
    $c.stf.setObjectValue(txb_IsuNm, arrPar[0].BAS_ISU_NM);
    $c.stf.setObjectValue(txb_IsuAbbrv, arrPar[0].BAS_ISU_ABBRV);
    $c.stf.setObjectValue(txb_IsuEngNm, arrPar[0].BAS_ISU_ENG_NM);
    $c.stf.setObjectValue(txb_IsuEngAbbrv, arrPar[0].BAS_ISU_ENG_ABBRV);
};


/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    var initTpCd = '';
    //관련기관-대표주관회사
    if (scwin.vSelObj.id == 'cmb_BndMajagntComCd') {
        initTpCd = '1';
    }
    //관련기관-보증기관
    else if (scwin.vSelObj.id == 'cmb_GrtInstCd') {
        initTpCd = '2';
    }
    //관련기관-등록기관
    else if (scwin.vSelObj.id == 'cmb_RegInstCd') {
        initTpCd = '3';
    }
    //관련기관-원리금지급대행
    else if (scwin.vSelObj.id == 'cmb_PrincintPayAgntCd') {
        initTpCd = '4';
    }
    //관련기관-수탁기관
    else if (scwin.vSelObj.id == 'cmb_TrstInstCd') {
        initTpCd = '5';
    }
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(scwin.vSelObj),
        INST_NM: $c.stf.getObjectValue(scwin.vSelObj),
        LBL_NM: '',
        INIT_TP_CD: initTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    if (typeof(arrPar[0].INST_CD) != 'undefined') {
        $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].INST_CD);
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
