/********************************************** 
 * 함수명   : fn_SetCreditCombo
 * 설명       : 신용평가기관을 설정한다.
 ***********************************************/
scwin.fn_SetCreditCombo = function(obj, cd, val) {
    var cbdata = "^ ," + cd + "^" + val;
    obj.CBData = cbdata;
    $c.stf.setObjectValue(obj, cd);
};


/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_SetUdwrtInst
 * 설명       : 인수기관 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInst = function(rowIdx, cbObj, edtObj) {
    var UDWRT_INST_CD = dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD');
    if (UDWRT_INST_CD == '9999') {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    } else {
        $c.stf.setObjectValue(cbObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_INST_CD'));
        $c.stf.setObjectValue(edtObj, dts_UdwrtInst.getCellData(rowIdx, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetSecutizAsstTpCd
 * 설명       : 유동화자산유형 설정한다.
 ***********************************************/
scwin.fn_SetSecutizAsstTpCd = function(rowIdx, cbObj) {
    //유동화자산유형
    $c.stf.setObjectValue(cbObj, dts_SecutizAsst.getCellData(rowIdx, 'SECUTIZ_ASST_TP_CD'));
    $c.stf.setObjectValue(txb_SecutizAsstTpMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'SECUTIZ_ASST_TP_MISC_CONTN'));
};


/********************************************** 
 * 함수명   : fn_SetSecutizAsstHdTpCd
 * 설명       : 자산보유자 설정한다.
 ***********************************************/
scwin.fn_SetSecutizAsstHdTpCd = function(rowIdx, cbHdTpObj, cbHdInstObj, cbAdmObj) {
    //자산보유자유형
    $c.stf.setObjectValue(cbHdTpObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_TP_CD'));
    $c.stf.setObjectValue(txb_AsstHdTpMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_TP_MISC_CONTN'));

    //자산보유자기관
    var cbdata = '';
    cbdata = "^ ," + dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_CD') + "^" + dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_NM');
    cbHdInstObj.CBData = cbdata;
    $c.stf.setObjectValue(cbHdInstObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_CD'));
    $c.stf.setObjectValue(txb_AsstHdInstMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_HD_INST_MISC_CONTN'));

    //자산관리자기관
    cbdata = "^ ," + dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_CD') + "^" + dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_NM');
    cbAdmObj.CBData = cbdata;
    $c.stf.setObjectValue(cbAdmObj, dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_CD'));
    $c.stf.setObjectValue(txb_AsstAdmInstMiscContn, dts_SecutizAsst.getCellData(rowIdx, 'ASST_ADM_INST_MISC_CONTN'));
};


