    $c.stf.setObjectValue(cmb_CreditValuInstCd1, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, '0');
    $c.stf.setObjectValue(cmb_SfValuYn1, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd2, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, '0');
    $c.stf.setObjectValue(cmb_SfValuYn2, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd3, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, '0');
    $c.stf.setObjectValue(cmb_SfValuYn3, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd4, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, '0');
    $c.stf.setObjectValue(cmb_SfValuYn4, '');
    if (rowcount > 0) {
        for (var idx = 1; idx <= rowcount; idx++) {
            if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9201') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd1, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn1, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9202') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd2, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn2, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9203') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd3, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn3, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9204') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd4, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn4, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            }
        }
